(()=>{
const sharedNote=document.querySelector('.settings-box > p');if(sharedNote)sharedNote.textContent='所有课件共用设置；只影响之后的生成，已保存内容不变。';
const button=document.createElement('button');button.className='pdf-upload-toggle';button.type='button';button.textContent='+';button.title='上传PDF课件';button.setAttribute('aria-label','上传PDF课件');document.querySelector('.brand').after(button);
const overlay=document.createElement('section');overlay.className='pdf-upload-overlay';overlay.hidden=true;overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','上传PDF课件');overlay.innerHTML='<div class="pdf-upload-box"><div class="pdf-upload-head"><h2>上传课件</h2><button id="uploadClose" aria-label="关闭上传">×</button></div><p>仅支持 PDF，最大60MB、300页。上传和导入不调用模型。</p><label>选择PDF<input id="uploadFile" type="file" accept=".pdf,application/pdf"></label><label>课程<input id="uploadCourse" maxlength="60" value="GEB3302"></label><label>课件名称<input id="uploadTitle" maxlength="120" placeholder="默认使用文件名"></label><progress id="uploadProgress" hidden max="100" value="0"></progress><p id="uploadNotice" role="status"></p><div class="pdf-upload-actions"><button id="uploadStart" class="primary">上传并导入</button><button id="uploadOpen" hidden>打开课件</button></div></div>';document.body.append(overlay);
const get=id=>document.getElementById(id);let pending=false,openURL=null;const jobKey='reader-pdf-import-job';
const notice=(message,error=false)=>{get('uploadNotice').textContent=message;get('uploadNotice').className=error?'pdf-upload-error':'';};
button.onclick=()=>{overlay.hidden=false;};get('uploadClose').onclick=()=>{overlay.hidden=true;};document.addEventListener('keydown',event=>{if(event.key==='Escape')overlay.hidden=true;});
get('uploadFile').onchange=()=>{const file=get('uploadFile').files[0];if(file&&!get('uploadTitle').value)get('uploadTitle').value=file.name.replace(/\.pdf$/i,'');};
get('uploadOpen').onclick=()=>{if(openURL)location.assign(openURL);};
async function updateLibrary(){const data=await(await fetch('/catalog.json')).json();catalog=data;for(const item of data.decks){if(Array.from($('deckSelect').options).some(option=>option.value===item.id))continue;let group=Array.from($('deckSelect').querySelectorAll('optgroup')).find(group=>group.label===item.course);if(!group){group=document.createElement('optgroup');group.label=item.course;$('deckSelect').append(group);}const option=document.createElement('option');option.value=item.id;option.textContent=item.course+' · '+item.title;group.append(option);}}
async function poll(id){try{const response=await fetch('/api/upload/jobs/'+id);const data=await response.json();if(!response.ok)throw Error(data.error||'无法读取导入任务');get('uploadProgress').hidden=false;
  if(data.state==='failed')throw Error(data.error||'导入失败');
  if(data.state==='ready'){pending=false;get('uploadStart').disabled=false;get('uploadProgress').value=100;notice('已导入 '+data.total+' 页，已加入课件列表');openURL='/decks/'+data.id+'/';get('uploadOpen').hidden=false;localStorage.removeItem(jobKey);await updateLibrary();return;}
  if(data.total){get('uploadProgress').value=Math.round(data.done/data.total*100);notice('正在导入：'+data.done+' / '+data.total+' 页');}else{get('uploadProgress').removeAttribute('value');notice('正在读取PDF…');}setTimeout(()=>poll(id),1200);
}catch(error){pending=false;get('uploadStart').disabled=false;localStorage.removeItem(jobKey);notice(error.message,true);}}
get('uploadStart').onclick=()=>{if(pending)return;const file=get('uploadFile').files[0];if(!file){notice('请选择PDF文件',true);return;}if(!/\.pdf$/i.test(file.name)){notice('只支持PDF，不接受PPT/PPTX',true);return;}if(file.size===0||file.size>60*1024*1024){notice('文件须在60MB以内且不能为空',true);return;}pending=true;get('uploadStart').disabled=true;get('uploadOpen').hidden=true;get('uploadProgress').hidden=false;get('uploadProgress').value=0;notice('正在上传…');
  const request=new XMLHttpRequest();request.open('POST','/api/upload');request.setRequestHeader('Content-Type','application/pdf');request.setRequestHeader('X-Filename',encodeURIComponent(file.name));request.setRequestHeader('X-Title',encodeURIComponent(get('uploadTitle').value));request.setRequestHeader('X-Course',encodeURIComponent(get('uploadCourse').value));request.upload.onprogress=event=>{if(event.lengthComputable)get('uploadProgress').value=Math.round(event.loaded/event.total*100);};request.onload=()=>{try{const result=JSON.parse(request.responseText);if(request.status!==202)throw Error(result.error||'上传失败');localStorage.setItem(jobKey,result.id);poll(result.id);}catch(error){pending=false;get('uploadStart').disabled=false;notice(error.message,true);}};request.onerror=()=>{pending=false;get('uploadStart').disabled=false;notice('连接中断，请检查网络后重试',true);};request.send(file);
};
const oldJob=localStorage.getItem(jobKey);if(oldJob){pending=true;get('uploadStart').disabled=true;poll(oldJob);}
})();
